import{_ as p,c as e,o as a,ah as r}from"./chunks/framework.l36K22_3.js";const m=JSON.parse('{"title":"2014，新的开始","description":"2014年2月14日， 元宵节快乐， 情人节快！ 不同往年，这个时候的我，还在出差中。出差的这几天（也是第一次以公司的名义出差），经历的种种，深有感触。 大学毕业那会，向往那种出差可以到处跑，到处玩，可以去了解一个地方的习俗等等，觉得很好玩...","frontmatter":{"title":"2014，新的开始","date":"2014-02-13T00:00:00.000Z","category":"diary","tags":["心情"],"slug":"2014-new-start","layout":"blog-post","description":"2014年2月14日， 元宵节快乐， 情人节快！ 不同往年，这个时候的我，还在出差中。出差的这几天（也是第一次以公司的名义出差），经历的种种，深有感触。 大学毕业那会，向往那种出差可以到处跑，到处玩，可以去了解一个地方的习俗等等，觉得很好玩..."},"headers":[],"relativePath":"blog/2014-new-start.md","filePath":"blog/posts/diary/2014-new-start.md","lastUpdated":1788854523000}'),s={name:"blog/2014-new-start.md"};function o(_,t,n,d,l,i){return a(),e("div",null,t[0]||(t[0]=[r("<p>2014年2月14日，</p><p>元宵节快乐，</p><p>情人节快！</p><p>不同往年，这个时候的我，还在出差中。出差的这几天（也是第一次以公司的名义出差），经历的种种，深有感触。</p><p>大学毕业那会，向往那种出差可以到处跑，到处玩，可以去了解一个地方的习俗等等，觉得很好玩，很开心。天天在外面，不知道是因为时间的关系，又或许是去年一年，自己成功转型为宅男，所以现在出差在外面，毫不习惯，没有归属感。</p><p>这几天，天天早出晚归，没时间去整理去思考一些东西，好吧，过年的时候我也没想过2014需要作哪些计划，这些都是拖延症惹的祸，但我相信，2013年是我停滞不前的一年，至此结束，2014年，重新出发。</p><p>2014年，</p><p>希望自己能培养跟工作除外的另外一些爱好，摄影除外的，让自己充实起来，而不是整天对着电脑打打游戏，看看电影，整天宅在家里。</p><p>在技术上，希望自己能坚持不懈，完善及完整自己的专业技术，不断学习。</p><p>把去年存下来欠着的书，看完，争取一个月一本书，但这不是给自己压力，而是兴趣。</p><p>也希望自己能够可以合理的安排好自己的时间。</p><p>加油吧！</p>",12)]))}const f=p(s,[["render",o]]);export{m as __pageData,f as default};
